mapper.sql:
WHERE 1=1
AND WI.작성일자 >= #{searchDtFrom}
AND WI.작성일자 <= #{searchDtTo}
AND WI.거래처코드 = #{searchBcncCode}
AND ( (SELECT TOP 1 UPPER(RTRIM(CM2.상호)) FROM 거래처MASTER CM2 WHERE CM2.거래처코드 = WI.거래처코드 ) LIKE UPPER('%'+ RTRIM(#{searchBcncNm}) +'%') OR (SELECT TOP 1 UPPER(RTRIM(거래처코드)) FROM 거래처MASTER CM2 WHERE CM2.거래처코드 = WI.거래처코드 ) LIKE UPPER('%'+ RTRIM(#{searchBcncNm}) +'%') )
AND (WI.답변 LIKE UPPER('%'+ #{searchTitle} +'%') OR WI.내용 LIKE UPPER('%'+ #{searchTitle} +'%'))

mapper.update:
UPDATE 웹거래처문의 SET
	진행상태 = #{WI_PROGRSSE}
	, 거래처작성자 = #{WI_BCNCWRTER}
	, 제목 = #{WI_TITLE}
	, 내용 = #{WI_CN}
	, 답변자 = #{bcncCode}
	, 답변 = #{WI_ANSWER}
	, 수정자 = #{bcncCode}
	, 수정일자 = CONVERT(VARCHAR,GETDATE(),112)
	, 수정시간 = REPLACE(CONVERT(VARCHAR,GETDATE(),108),':','')
WHERE 일련번호 = #{WI_ID}
